import {safeLink} from './spark-model.js';
export function taskLinks(text){const rows=text.split('\n').map(s=>s.trim()).filter(Boolean);if(rows.length>10)throw Error('Use no máximo 10 links.');return rows.map(row=>{const i=row.indexOf('|');return {label:(i<0?'Documento':row.slice(0,i).trim()).slice(0,160),url:safeLink((i<0?row:row.slice(i+1)).trim())};});}
export function taskCriteria(rows,grading){if(!rows.length||rows.length>20)throw Error('Cadastre de 1 a 20 critérios.');return rows.map(r=>{const name=String(r.name||'').trim(),description=String(r.description||'').trim(),points=grading==='grade'?Number(r.points):0;if(!name||name.length>200||description.length>2000||!Number.isFinite(points)||points<0)throw Error('Confira nomes, descrições e valores dos critérios.');return {name,description,points};});}
export function taskGrade(task,values,feedback){if(values.length!==task.criteria.length)throw Error('Corrija todos os critérios.');const criteria=task.criteria.map((c,i)=>{const v=task.grading==='concept'?values[i]:Number(values[i]);if(task.grading==='concept'?!['A','B','C','D'].includes(v):!Number.isFinite(v)||v<0||v>c.points)throw Error('Resultado inválido no critério '+c.name);return {...c,value:v};});return {grading:task.grading,criteria,feedback:String(feedback||'').slice(0,5000),...(task.grading==='grade'?{grade:criteria.reduce((s,c)=>s+c.value,0),scale:task.criteria.reduce((s,c)=>s+c.points,0)}:{})};}
